const body = items[0].json.body;
let text = body.message.text || '';
// Remove problematic characters and trim
text = text.replace(/[\"\r\n]/g, ' ').trim();

return [{
  json: {
    chat_id: body.message.chat.id,
    user_text: text,
    username: body.message.from.username || 'unknown',
    raw_payload: body
  }
}];
